head.script:
///////// 1. 변수 및 선언 영역 /////////
scwin.screenId = "jlddst15200";
scwin.title_of_account1 = null;
scwin.title_of_account2 = null;
scwin.finstat = undefined;
scwin.finrate = undefined;

///////// 2. 초기화 영역 /////////
/**
 * @method
 * @name init_nowVars
 * @description 현재 시각 파생값 충전 — as-is JSP 계산분(서버 데이터 아님)
 * @returns {void}
 * @hidden N
 */
scwin.init_nowVars = function () {
    const pc = $c.util.getComponent('dma_pageContext');
    if (!pc || !pc.set || !pc.get) { return; }
    if (!pc.get("nowYear")) { pc.set("nowYear", $c.date.getServerDateTime("yyyy")); }
};

// 연도 선택 항목 — as-is 가 서버에서 그리던 범위를 화면에서 세운다(값 원천 = dma_pageContext.nowYear).

/**
 * @method
 * @name init_yearItems
 * @description 초기화 — year Items
 * @returns {void}
 * @hidden N
 */
scwin.init_yearItems = function () {
    const pc = $c.util.getComponent("dma_pageContext");
    const ny = Number(pc && pc.get ? pc.get("nowYear") : 0);
    if (!ny) { /* TODO Stage2: [sdd] 연도 선택 — nowYear 미충전(init_nowVars 앞에서 불렸다) */ return 0; }
    {
        const s = $c.util.getComponent("slc_fiscalyear");
        if (!s || typeof s.addItem !== "function") { /* TODO Stage2: [sdd] 연도 선택 대상 부재:  "slc_fiscalyear */ }
        else {
            if (typeof s.removeAll === "function") { s.removeAll(); }
            for (let i = 0; i <= (ny - 1996); i++) {
                const y = String(ny - (i - (0)) * 1);
                s.addItem(y, y);
            }
            s.setValue(String((ny - 1)));
        }
    }
    return 1;
};

/**
 * @method
 * @name init
 * @description 화면 초기화 — 파라미터 수신·기본값·컴포넌트 초기 설정(onpageload 에서 순차 호출)
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.init = async function () {
    scwin.title_of_account2.setStyle("display", "none");
    await scwin.fnSearch(false);
};

/**
 * @method
 * @name init_pageBody
 * @description 초기화 — page Body
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.init_pageBody = async function () {
    try {
        await scwin.init();

    } catch (_ex) { await $c.exception.handleError(_ex, { context: 'jlddst15200.onpageload' }); }
};

/**
 * @method
 * @name init_recvParam
 * @description 화면 전환 파라미터 수신 — $c.data.getParameter() 를 dma_pageContext 에 담는다
 * @returns {void}
 * @hidden N
 */
scwin.init_recvParam = function () { dma_pageContext.setJSON($c.data.getParameter() ?? {}); };

try { scwin.finstat =["A010","A040","A080","A090","A100","A110","A120","A130","A140","A160","A170","A180","A190","A200"]; } catch (_e) { $c.exception.handleError(_e, { notify: 'none', context: 'jlddst15200' }); }

try { scwin.finrate =["B010","B020","B030","B040","B050","B060","B080","B090","B100","B110"]; } catch (_e) { $c.exception.handleError(_e, { notify: 'none', context: 'jlddst15200' }); }

/**
 * @method
 * @name onpageload
 * @description 화면 로딩 시 초기 처리 — init 순차 호출
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.onpageload = async function () {
    try {
        scwin.title_of_account1 = $c.util.getComponent('title_of_account1');
        scwin.title_of_account2 = $c.util.getComponent('title_of_account2');
        scwin.init_recvParam();
        scwin.init_nowVars();
        scwin.init_yearItems();
        await scwin.init_pageBody();
    } catch (e) {
        await $c.exception.handleError(e, { context: 'jlddst15200.onpageload' });
    }
};

///////// 3. 컴포넌트 이벤트 영역 /////////
/**
 * @method
 * @name slc_ordergubun_onchange
 * @description slc_ordergubun 변경 이벤트
 * @param {Object} e 이벤트 객체
 * @returns {void}
 * @hidden N
 */
scwin.slc_ordergubun_onchange = function(e){
    try {
        scwin.changeOrder(); return false;

    } catch (_ex) { $c.exception.handleError(_ex, { context: 'jlddst15200.slc_ordergubun_onchange' }); }
};

/**
 * @method
 * @name slc_basisAccnt_onchange
 * @description slc_basisAccnt 변경 이벤트
 * @param {Object} e 이벤트 객체
 * @returns {void}
 * @hidden N
 */
scwin.slc_basisAccnt_onchange = function(e){
    try {
        const ev = e;
        const selfVar = (ev && (ev.element || ev.target || ev.srcElement)) || this;
        scwin.checkAccount(selfVar.id);

    } catch (_ex) { $c.exception.handleError(_ex, { context: 'jlddst15200.slc_basisAccnt_onchange' }); }
};

/**
 * @method
 * @name btn_changeTitleOfAccountPanel_onclick
 * @description btn_changeTitleOfAccountPanel 클릭 이벤트
 * @param {Object} e 이벤트 객체
 * @returns {void}
 * @hidden N
 */
scwin.btn_changeTitleOfAccountPanel_onclick = function(e){
    try {
        scwin.changeTitleOfAccountPanel(); return false;

    } catch (_ex) { $c.exception.handleError(_ex, { context: 'jlddst15200.btn_changeTitleOfAccountPanel_onclick' }); }
};

/**
 * @method
 * @name ipt_chAll1_onclick
 * @description ipt_chAll1 클릭 이벤트
 * @param {Object} e 이벤트 객체
 * @returns {void}
 * @hidden N
 */
scwin.ipt_chAll1_onclick = function(e){
    try {
        scwin.changeAllCheckState()

    } catch (_ex) { $c.exception.handleError(_ex, { context: 'jlddst15200.ipt_chAll1_onclick' }); }
};

/**
 * @method
 * @name ipt_chAll2_onclick
 * @description ipt_chAll2 클릭 이벤트
 * @param {Object} e 이벤트 객체
 * @returns {void}
 * @hidden N
 */
scwin.ipt_chAll2_onclick = function(e){
    try {
        scwin.changeAllCheckState()

    } catch (_ex) { $c.exception.handleError(_ex, { context: 'jlddst15200.ipt_chAll2_onclick' }); }
};

/**
 * @method
 * @name btn_fnSearch_onclick
 * @description btn_fnSearch 클릭 이벤트
 * @param {Object} e 이벤트 객체
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.btn_fnSearch_onclick = async function(e){
    try {
        await scwin.fnSearch(false); return false;

    } catch (_ex) { await $c.exception.handleError(_ex, { context: 'jlddst15200.btn_fnSearch_onclick' }); }
};

/**
 * @method
 * @name btn_fnDownload_onclick
 * @description btn_fnDownload 클릭 이벤트
 * @param {Object} e 이벤트 객체
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.btn_fnDownload_onclick = async function(e){
    try {
        await scwin.fnDownload(); return false;

    } catch (_ex) { await $c.exception.handleError(_ex, { context: 'jlddst15200.btn_fnDownload_onclick' }); }
};

///////// 4. 서브미션 콜백 영역 /////////
/**
 * @method
 * @name tx_fnDownload
 * @description fn Download 서버 호출
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.tx_fnDownload = async function () {
    const sbmOptions = {
        id: "tx_fnDownload",
        method: "post",
        action: "/compfinance/financialinfo.do",
        ref: "dma_fnDownloadReq",
        isProcessMsg: false
    };
    const res = await $c.sbm.executeDynamic(sbmOptions);
    if (res && res.skipped) { return res; }  // 중복 제출 skip
    if (!(res && res.responseJSON && res.responseJSON.success === true)) {
        const m = (res && res.responseJSON && res.responseJSON.message) || $c.sbm.getStatusMessage(res) || ('서버 응답 오류 (' + $c.sbm.getResultCode(res) + ')');
        await $c.win.alert(m);
    }
    return res;
};

/**
 * @method
 * @name tx_fnSearch_ajaxsubmit
 * @description fn Search ajaxsubmit 서버 호출
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.tx_fnSearch_ajaxsubmit = async function () {
    const sbmOptions = {
        id: "tx_fnSearch_ajaxsubmit",
        method: "post",
        action: "/compfinance/financialinfo.do",
        ref: "dma_fnSearchAjaxsubmitReq",
        isProcessMsg: false
    };
    const res = await $c.sbm.executeDynamic(sbmOptions);
    if (res && res.skipped) { return res; }  // 중복 제출 skip
    if (!(res && res.responseJSON && res.responseJSON.success === true)) {
        const m = (res && res.responseJSON && res.responseJSON.message) || $c.sbm.getStatusMessage(res) || ('서버 응답 오류 (' + $c.sbm.getResultCode(res) + ')');
        await $c.win.alert(m);
    }
    return res;
};

///////// 5. 일반/업무 함수 영역 /////////
/**
 * @method
 * @name fnOrder
 * @description fn Order 처리
 * @param {*} mode mode
 * @param {*} stat stat
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.fnOrder = async function (mode, stat) {
    $c.util.getComponent("dma_fnDownloadReq").set("orderMode", mode);
    $c.util.getComponent("dma_fnDownloadReq").set("orderStat", stat);
    $("#searchForm > #pageIndex").val("1");
    await scwin.fnSearch(true);
};

/**
 * @method
 * @name fnSearch
 * @description fn Search 처리
 * @param {*} isOrder isOrder
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.fnSearch = async function (isOrder) {
    if (!isOrder) {
        scwin.setOrderway();
        scwin.setOrderby();
    }
    const titleofaccnt = scwin.makeTitleOfAccountParamString();
    $c.util.getComponent('ipt_titleofaccnt').setValue(titleofaccnt);
    $c.util.getComponent("dma_fnDownloadReq").set("method", "searchCorpOrder");
    $c.util.getComponent("dma_fnDownloadReq").set("forward", "list");
    await scwin.tx_fnSearch_ajaxsubmit();
};

/**
 * @method
 * @name fnSearchCallBack1
 * @description fn Search Call Back1 처리
 * @param {*} data 데이터
 * @returns {void}
 * @hidden N
 */
scwin.fnSearchCallBack1 = function (data) {
    $("#mainContents").empty().append(data);
    /* TODO Stage2: [sdd] 미실현(재설계 분류 #128): fnLegendTooltip( " ') */
};

/**
 * @method
 * @name changeTitleOfAccountPanel
 * @description change Title Of Account Panel 처리
 * @returns {void}
 * @hidden N
 */
scwin.changeTitleOfAccountPanel = function () {
    const val = $c.util.getComponent('slc_fininfotype').getValue();
    if (val === "finstat") {
        scwin.title_of_account1.setStyle("display", "");
        scwin.title_of_account2.setStyle("display", "none");
        $c.util.getComponent('ipt_finsearchtype').setValue("finstat");
    } else {
        if (val === "finrate") {
            scwin.title_of_account1.setStyle("display", "none");
            scwin.title_of_account2.setStyle("display", "");
            $c.util.getComponent('ipt_finsearchtype').setValue("finrate");
        }
    }
    scwin.makeSelectBox(val);
};

/**
 * @method
 * @name makeTitleOfAccountParamString
 * @description make Title Of Account Param String 처리
 * @returns {void}
 * @hidden N
 */
scwin.makeTitleOfAccountParamString = function () {
    let paramString = "";
    const id = "";
    let flag = false;
    paramString = "";
    const finsearchtype = $c.util.getComponent('ipt_finsearchtype').getValue();
    if (finsearchtype === "finstat") {
        for (let i = 0; i < scwin.finstat.length; i++) {
            flag = scwin.checkChkBoxStatus(scwin.finstat[i]);
            if (flag) {
                paramString += scwin.finstat[i];
                if (i !== (scwin.finstat.length - 1)) {
                    paramString += "|";
                }
            }
        }
    } else {
        if (finsearchtype === "finrate") {
            for (let i = 0; i < scwin.finrate.length; i++) {
                flag = scwin.checkChkBoxStatus(scwin.finrate[i]);
                if (flag) {
                    paramString += scwin.finrate[i];
                    if (i !== (scwin.finrate.length - 1)) {
                        paramString += "|";
                    }
                }
            }
        }
    }
    return "finmm|" + paramString;
};

/**
 * @method
 * @name checkChkBoxStatus
 * @description check Chk Box Status 처리
 * @param {*} id id
 * @returns {void}
 * @hidden N
 */
scwin.checkChkBoxStatus = function (id) {
    return $("#" + id).is(":checked");
};

/**
 * @method
 * @name makeSelectBox
 * @description make Select Box 처리
 * @param {*} val val
 * @returns {void}
 * @hidden N
 */
scwin.makeSelectBox = function (val) {
    (($c.util.getComponent('slc_basisAccnt')) && ($c.util.getComponent('slc_basisAccnt')).removeAll ? ($c.util.getComponent('slc_basisAccnt')).removeAll() : (($c.util.getComponent('slc_basisAccnt')) && ($c.util.getComponent('slc_basisAccnt')).setValue ? ($c.util.getComponent('slc_basisAccnt')).setValue('') : void 0));
    if (val === "finstat") {
        $c.util.getComponent('slc_basisAccnt').addItem("A010", "유동자산");
        $c.util.getComponent('slc_basisAccnt').addItem("A040", "고정자산");
        $c.util.getComponent('slc_basisAccnt').addItem("A080", "자산총계");
        $c.util.getComponent('slc_basisAccnt').addItem("A090", "유동부채");
        $c.util.getComponent('slc_basisAccnt').addItem("A100", "고정부채");
        $c.util.getComponent('slc_basisAccnt').addItem("A110", "부채총계");
        $c.util.getComponent('slc_basisAccnt').addItem("A120", "자본금");
        $c.util.getComponent('slc_basisAccnt').addItem("A130", "자본잉여금");
        $c.util.getComponent('slc_basisAccnt').addItem("A140", "이익잉여금");
        $c.util.getComponent('slc_basisAccnt').addItem("A160", "자본총계");
        $c.util.getComponent('slc_basisAccnt').addItem("A170", "매출액(수익)");
        $c.util.getComponent('slc_basisAccnt').addItem("A180", "영업이익");
        $c.util.getComponent('slc_basisAccnt').addItem("A190", "법인세차감전계속사업이익");
        $c.util.getComponent('slc_basisAccnt').addItem("A200", "당기순이익");
    } else {
        if (val === "finrate") {
            $c.util.getComponent('slc_basisAccnt').addItem("B020", "부채비율");
            $c.util.getComponent('slc_basisAccnt').addItem("B030", "총자산증가율");
            $c.util.getComponent('slc_basisAccnt').addItem("B040", "매출액증가율");
            $c.util.getComponent('slc_basisAccnt').addItem("B050", "순이익증가율");
            $c.util.getComponent('slc_basisAccnt').addItem("B060", "영업이익증가율");
            $c.util.getComponent('slc_basisAccnt').addItem("B080", "총자본순이익율");
            $c.util.getComponent('slc_basisAccnt').addItem("B090", "자기자본율");
        }
    }
    scwin.setOrderby();
};

/**
 * @method
 * @name setOrderby
 * @description set Orderby 처리
 * @returns {void}
 * @hidden N
 */
scwin.setOrderby = function () {
    $c.util.getComponent('ipt_orderMode').setValue(($c.util.getComponent("slc_basisAccnt").getValue() || ''));
};

/**
 * @method
 * @name checkAccount
 * @description check Account 처리
 * @param {*} id id
 * @returns {void}
 * @hidden N
 */
scwin.checkAccount = function (id) {
    const val = $("#" + id).val();
    $("#" + val).attr("checked", true);
};

/**
 * @method
 * @name changeAllCheckState
 * @description change All Check State 처리
 * @returns {void}
 * @hidden N
 */
scwin.changeAllCheckState = function () {
    const val = $c.util.getComponent('slc_fininfotype').getValue();
    if (val === "finstat") {
        for (let i = 0; i < scwin.finstat.length; i++) {
            if ($("#ipt_chAll1").is(":checked")) {
                $("#" + scwin.finstat[i]).attr("checked", true);
            } else {
                $("#" + scwin.finstat[i]).attr("checked", false);
            }
        }
    } else {
        if (val === "finrate") {
            for (let i = 0; i < scwin.finrate.length; i++) {
                if ($("#ipt_chAll2").is(":checked")) {
                    $("#" + scwin.finrate[i]).attr("checked", true);
                } else {
                    $("#" + scwin.finrate[i]).attr("checked", false);
                }
            }
        }
    }
};

/**
 * @method
 * @name fnDownload
 * @description fn Download 처리
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.fnDownload = async function () {
    const titleofaccnt = scwin.makeTitleOfAccountParamString();
    $c.util.getComponent('ipt_titleofaccnt').setValue(titleofaccnt);
    $c.util.getComponent("dma_fnDownloadReq").set("method", "download_order");
    $c.util.getComponent("dma_fnDownloadReq").set("forward", "download_order");
    await scwin.tx_fnDownload();
};

/**
 * @method
 * @name setOrderway
 * @description set Orderway 처리
 * @returns {void}
 * @hidden N
 */
scwin.setOrderway = function () {
    scwin.changeOrder();
};

/**
 * @method
 * @name changeOrder
 * @description change Order 처리
 * @returns {void}
 * @hidden N
 */
scwin.changeOrder = function () {
    const gubun = $c.util.getComponent('slc_ordergubun').getValue();
    if (gubun === "up30") {
        $c.util.getComponent('ipt_orderStat').setValue("D");
    } else {
        if (gubun === "down30") {
            $c.util.getComponent('ipt_orderStat').setValue("A");
        }
    }
};
